const v = $json;
const nome = v.nome_cliente || 'cliente';
const convite = v.reativacao_objetivo === 'novo_servico'
  ? 'Gostaria de agendar um novo serviço?'
  : 'Gostaria de agendar a manutenção de ' + v.nome_servico + '?';
const mensagem = 'Olá, ' + nome + '! Já faz um tempo desde seu atendimento de ' + v.nome_servico + ' em ' + v.nome_fantasia + '. ' + convite;
return {json: {...v, mensagem}};
